// TypeScript Version: 4.1

/**
* Immutably unsets a value at a path in a document using structural sharing.
*
* @param document - source document
* @param tokens - array of reference tokens
* @throws tokens must not be empty
* @throws tokens must not contain unsafe tokens
* @throws intermediate path segments must reference objects or arrays
* @returns new document with the value at the specified path removed
*
* @example
* var doc = {
*     'a': {
*         'b': 1,
*         'c': 2
*     }
* };
* var out = unset( doc, [ 'a', 'b' ] );
* // returns { 'a': { 'c': 2 } }
*
* var bool = ( doc.a === out.a );
* // returns false
*
* bool = ( doc === out );
* // returns false
*/
declare function unset( document: Array<any> | Record<string, any>, tokens: Array<string> ): any;


// EXPORTS //

export = unset;
